import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"大過","description":"周易集解 - 大過","frontmatter":{"title":"大過","description":"周易集解 - 大過"},"headers":[],"relativePath":"zh/classics/jijie/028.md","filePath":"zh/classics/jijie/028.md"}'),l={name:"zh/classics/jijie/028.md"};function n(d,a,t,s,p,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="大過" tabindex="-1">大過 <a class="header-anchor" href="#大過" aria-label="Permalink to “大過”">​</a></h1><h2 id="大過-1" tabindex="-1">大過 <a class="header-anchor" href="#大過-1" aria-label="Permalink to “大過”">​</a></h2><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>大過，棟橈。利有攸往，亨。</p><h2 id="卦辞注" tabindex="-1">卦辞注 <a class="header-anchor" href="#卦辞注" aria-label="Permalink to “卦辞注”">​</a></h2><p>《序卦》曰：不養則不可動，故受之以大過。</p><p>崔憬曰：養則可動，動則過厚，故受之以大過也。</p><p>虞翻曰：大壯五之三，或兌三之五。棟橈謂三。巽為長木，稱棟。初上陰柔，本末弱，故棟橈也。</p><p>虞翻曰：謂二也。剛過而中，失位無應，利變應五；之外稱往，故利有攸往，乃亨也。</p><h2 id="彖" tabindex="-1">彖 <a class="header-anchor" href="#彖" aria-label="Permalink to “彖”">​</a></h2><p>《彖》曰：大過，大者過也。棟橈，本末弱也。剛過而中，巽而說行，利有攸往，乃亨。大過之時大矣哉。</p><h2 id="彖传注" tabindex="-1">彖传注 <a class="header-anchor" href="#彖传注" aria-label="Permalink to “彖传注”">​</a></h2><p>虞翻曰：陽稱大，謂二也。二失位，故大者過也。</p><p>向秀曰：棟橈則屋壞，主弱則國荒。所以橈，由於初上兩陰爻也。初為善始，末是令終。始終皆弱，所以棟橈。</p><p>王弼曰：初為本而上為末也。</p><p>侯果曰：本，君也。末，臣也。君臣俱弱，棟橈者也。</p><p>虞翻曰：剛過而中，謂二。說，兌也。故利有攸往。大壯震五之初，故亨。與遯同義。</p><p>虞翻曰：國之大事，在祀與戎，藉用白茅。女妻有子，繼世承祀，故大矣哉。</p><h2 id="象" tabindex="-1">象 <a class="header-anchor" href="#象" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：澤滅木，大過。君子以獨立不懼，遯世無悶。</p><h2 id="象传注" tabindex="-1">象传注 <a class="header-anchor" href="#象传注" aria-label="Permalink to “象传注”">​</a></h2><p>案：兌，澤也。巽，木漫也。凡木生近水者楊也，遇澤太過，木則漫滅焉。二五枯楊，是其義。</p><p>虞翻曰：君子謂乾初。陽伏巽中，體復一爻，潛龍之德，故稱獨立不懼。違則憂之，乾初同義，故遯世無悶也。</p><h2 id="初六" tabindex="-1">初六 <a class="header-anchor" href="#初六" aria-label="Permalink to “初六”">​</a></h2><p>初六，藉用白茅，無咎。</p><h2 id="初六注" tabindex="-1">初六注 <a class="header-anchor" href="#初六注" aria-label="Permalink to “初六注”">​</a></h2><p>虞翻曰：位在下稱藉，巽柔白為茅，故藉用白茅。失位，咎也。承二過四，應五士夫，故無咎矣。</p><h2 id="象-1" tabindex="-1">象 <a class="header-anchor" href="#象-1" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：藉用白茅，柔在下也。</p><h2 id="象传注-1" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-1" aria-label="Permalink to “象传注”">​</a></h2><p>侯果曰：以柔處下，履非其正，咎也。苟能絜誠肅恭不怠，雖置羞於地，可以薦奉，況藉用白茅，重慎之至，何咎之有矣。</p><h2 id="九二" tabindex="-1">九二 <a class="header-anchor" href="#九二" aria-label="Permalink to “九二”">​</a></h2><p>九二，枯楊生稊，老夫得其女妻，無不利。</p><h2 id="九二注" tabindex="-1">九二注 <a class="header-anchor" href="#九二注" aria-label="Permalink to “九二注”">​</a></h2><p>虞翻曰，稊，穉也。楊葉未舒稱稊。巽為楊，乾為老，老楊故枯。陽在二也。十二月時，周之二月。兌為雨澤，枯楊得澤復生稊。二體乾老，故稱老夫。女妻謂上兌，兌為少女，故曰女妻。大過之家，過以相與，老夫得其女妻，故無不利。</p><h2 id="象-2" tabindex="-1">象 <a class="header-anchor" href="#象-2" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：老夫女妻，過以相與也。</p><h2 id="象传注-2" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-2" aria-label="Permalink to “象传注”">​</a></h2><p>虞翻曰：謂二過初與五，五過上與二。獨大過之爻得過其應，故過以相與也。</p><h2 id="九三" tabindex="-1">九三 <a class="header-anchor" href="#九三" aria-label="Permalink to “九三”">​</a></h2><p>九三，棟橈，凶。《象》曰：棟橈之凶，不可以有輔也。</p><h2 id="象-3" tabindex="-1">象 <a class="header-anchor" href="#象-3" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：棟橈之凶，不可以有輔也。</p><h2 id="象传注-3" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-3" aria-label="Permalink to “象传注”">​</a></h2><p>虞翻曰：本末弱，故橈。輔之益橈，故不可以有輔。陽以陰為輔也。</p><h2 id="九四" tabindex="-1">九四 <a class="header-anchor" href="#九四" aria-label="Permalink to “九四”">​</a></h2><p>九四，棟隆，吉。有它吝。</p><h2 id="九四注" tabindex="-1">九四注 <a class="header-anchor" href="#九四注" aria-label="Permalink to “九四注”">​</a></h2><p>虞翻曰：隆，上也。應在於初。已與五，意在於上。故棟隆吉。失位，動入險而陷於井，故有他吝。</p><h2 id="象-4" tabindex="-1">象 <a class="header-anchor" href="#象-4" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：棟隆之吉，不橈乎下也。</p><h2 id="象传注-4" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-4" aria-label="Permalink to “象传注”">​</a></h2><p>虞翻曰：乾為動直，遠初近上，故不橈下也。</p><h2 id="九五" tabindex="-1">九五 <a class="header-anchor" href="#九五" aria-label="Permalink to “九五”">​</a></h2><p>九五，枯楊生華，老婦得其士夫，無咎無譽。</p><h2 id="九五注" tabindex="-1">九五注 <a class="header-anchor" href="#九五注" aria-label="Permalink to “九五注”">​</a></h2><p>虞翻曰：陽在五也。夬三月時，周之五月。枯楊得澤，故生華矣。老婦謂初，巽為婦，乾為老，故稱老婦也。士夫謂五。大壯震為夫，兌為少，故稱士夫。五過二，使應上。二過五，使取初。五得位，故無咎。陰在二多譽，今退伏初，故無譽。體姤淫女，故過以相與。使應少夫。《象》曰：｢亦可醜也。｣舊說以初為女妻，上為老婦，誤矣。馬君亦然。荀公以初陰失正，當變，數六，為女妻。二陽失正，數九，為老夫。以五陽得正位，不變，數七，為士夫。上陰得正，數八，為老婦。此何異俗說也。悲夫學之難，而以初本為小，反以上末為老。後之達者，詳其義焉。</p><h2 id="象-5" tabindex="-1">象 <a class="header-anchor" href="#象-5" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：枯楊生華，何可久也。老婦士夫，亦可醜也。</p><h2 id="象传注-5" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-5" aria-label="Permalink to “象传注”">​</a></h2><p>虞翻曰：乾為久，枯而生華，故不可久也。婦體姤淫，故可醜也。</p><h2 id="上六" tabindex="-1">上六 <a class="header-anchor" href="#上六" aria-label="Permalink to “上六”">​</a></h2><p>上六，過涉滅頂，凶，無咎。</p><h2 id="上六注" tabindex="-1">上六注 <a class="header-anchor" href="#上六注" aria-label="Permalink to “上六注”">​</a></h2><p>虞翻曰：大壯震為足，兌為水澤。震足沒水，故過涉也。頂，首也。乾為頂，頂沒兌水中，故滅頂凶。乘剛，咎也。得位，故無咎。與滅耳同義也。</p><h2 id="象-6" tabindex="-1">象 <a class="header-anchor" href="#象-6" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：過涉之凶，不可咎也。</p><h2 id="象传注-6" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-6" aria-label="Permalink to “象传注”">​</a></h2><p>《九家易》曰：君子以禮義為法，小人以畏慎為宜。至於大過之世，不復遵常，故君子犯義，小人犯刑。而家家有誅絕之罪。不可咎也。大過之世，君子遜遯，不行禮義，謂當不義則爭之，若比干諫而死是也。桀紂之民，可比屋而誅。上化致然，亦不可咎。曾子曰：上失其道，民散久矣。如得其情，則哀矜而勿喜，是其義也。</p>',69)])])}const f=e(l,[["render",n]]);export{b as __pageData,f as default};
